package com.turboio.addon;

import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;

/** Production automatic session/schedule/producer/outbox over real HTTP. */
public final class AudioSyncSessionTest {
 static int checks;static void yes(boolean v){checks++;if(!v)throw new AssertionError("audio session "+checks);}interface Work{void run()throws Exception;}
 static void code(Work work,String expected)throws Exception{try{work.run();throw new AssertionError("session accepted");}catch(IOException e){yes(expected.equals(e.getMessage()));}}
 static Map<String,Object> map(Object value){return WireJson.map(value);}static byte[] bytes(File file)throws IOException{return Files.readAllBytes(file.toPath());}
 static List<Object> archives(File files,long now)throws Exception{File manager=new File(files,"lifelog-audio/manager.json");if(!manager.exists()){String message=new String(WireJson.bytes(WireJson.object("taskId",LifelogAudioPayloadsTest.TASK,"mode",1,"frameCount",2)),"UTF-8");return Arrays.asList(LifelogAudioPayloadsTest.archive(files,now,"A3",message,false));}try(LifelogAudioManager m=new LifelogAudioManager(files,LifelogAudioPayloadsTest.A,LifelogAudioPayloadsTest.P,1,LifelogAudioPayloadsTest.C,LifelogAudioManager.Limits.standard(),()->{})){return m.catalog();}}
 static void text(File files,MaterialConnection connection,Map<String,Object> fixture,long now,boolean second)throws Exception{try(MaterialOutbox q=new MaterialOutbox(files,connection)){LifelogAudioPayloadsTest.ack(q,map(fixture.get(second?"material_event_2":"material_event")),fixture.get(second?"material_ack_2":"material_ack"),now);}}
 static AudioSyncSession session(File files,MaterialConfig text,AudioConfig audio,AudioSyncSession.Sources source,AudioUploadOutbox.Guard guard,MaterialApi.Transport http,AtomicLong now){return new AudioSyncSession(files,files,text,audio,source,guard,http,now::get);}
 public static void main(String[] args)throws Exception{
  File files=new File(args[0]).getCanonicalFile();Map<String,Object> fixture=map(WireJson.read(bytes(new File(args[1])),4194304,20000));String mode=args[2];AtomicLong now=new AtomicLong(AudioUploadWire.number(fixture.get("now")));AudioConnection audioConnection=AudioConnection.parse(WireJson.bytes(fixture.get("connection")),now.get());Map<String,Object> raw=map(WireJson.copy(fixture.get("text_connection")));raw.put("format",MaterialConnection.FORMAT);MaterialConnection material=MaterialConnection.parse(WireJson.bytes(raw),now.get());MaterialConfig text=new MaterialConfig(material,LifelogAudioPayloadsTest.A,true);AudioConfig audio=new AudioConfig(audioConnection,text.account,true);
  text(files,material,fixture,now.get(),false);List<Object> archive=archives(files,now.get()),sessions=LifelogAudioPayloadsTest.sessions(files,now.get());AudioSyncSession.Catalog catalog=new AudioSyncSession.Catalog(text.account,sessions,archive);AtomicInteger reads=new AtomicInteger();AtomicBoolean allowed=new AtomicBoolean(true);AudioUploadHttpTest.Loopback http=new AudioUploadHttpTest.Loopback((String)fixture.get("endpoint"),audioConnection.token(),mode.equals("pause-part")?"pause-part":"session",allowed);
  AudioUploadOutbox.Guard guard=()->{if(!allowed.get())throw new IOException("AUDIO_PAUSED");if(mode.equals("crash-enqueued")){File f=new File(files,"lifelog-audio-uploads/state.json");if(f.isFile())for(Object value:WireJson.list(map(WireJson.read(bytes(f),4194304,100000)).get("rows"))){Map<String,Object> r=map(value);if("queued".equals(r.get("state"))&&!"".equals(r.get("origin")))Runtime.getRuntime().halt(84);}}};
  AudioSyncSession.Sources source=account->{reads.incrementAndGet();if(mode.equals("resume-no-source"))throw new IOException("AUDIO_CATALOG_UNAVAILABLE");return catalog;};
  AudioSyncSession engine=session(files,text,audio,source,guard,http,now);AudioSyncSession.Status status;
  if(mode.equals("pause-part")){code(()->engine.run(false,2,8),"AUDIO_PAUSED");allowed.set(true);now.addAndGet(120001);AudioUploadHttpTest.Loopback recovery=new AudioUploadHttpTest.Loopback((String)fixture.get("endpoint"),audioConnection.token(),"session",allowed);status=session(files,text,audio,a->{throw new IOException("AUDIO_CATALOG_UNAVAILABLE");},guard,recovery,now).run(false,2,8);yes(status.retained==1&&status.prepared==0&&recovery.parts==0&&http.parts==1);}
  else status=engine.run(false,2,8);
  yes(status.retained==1&&status.rows.size()==1);Map<String,Object> row=map(status.rows.get(0));yes(AudioSyncSession.origin(map(archive.get(0))).equals(row.get("origin")));yes(Boolean.FALSE.equals(map(row.get("receipt")).get("recording_completeness_verified")));
  Map<String,Object> receipt=map(WireJson.copy(row.get("receipt")));int parts=http.parts;
  if(mode.equals("full")){
   AudioSyncSession.Status repeat=engine.run(false,2,8,true);yes(repeat.prepared==0&&repeat.pumped==0&&repeat.retained==1&&http.parts==parts);yes(receipt.equals(map(repeat.rows.get(0)).get("receipt")));int requests=http.posts,sourceReads=reads.get();AudioSyncSession.Status waiting=engine.run(false,2,8);yes(!waiting.attempted&&http.posts==requests&&reads.get()==sourceReads);
   code(()->session(files,text.enabled(false),audio,source,guard,http,now).run(false,2,8),"AUDIO_PAUSED");yes(http.posts==requests);
   // A newly queued text revision fences existing audio until it is stored.
   File gated=new File(files,"gated");yes(gated.mkdir());text(gated,material,fixture,now.get(),false);List<Object> gatedArchives=archives(gated,now.get()),gatedSessions=LifelogAudioPayloadsTest.sessions(gated,now.get());Map<String,Object> gatedArchive=map(gatedArchives.get(0));try(MaterialOutbox q=new MaterialOutbox(gated,material);LifelogAudioPayloads p=new LifelogAudioPayloads(gated,text.account,()->{});AudioUploadOutbox audioQueue=new AudioUploadOutbox(gated,audioConnection,text.account,()->{})){LifelogAudioPayloads.Prepared prepared=p.prepare(LifelogAudioPayloads.TextSource.stored(q,material,audioConnection,(String)map(gatedSessions.get(0)).get("material_id")),map(gatedSessions.get(0)),gatedArchive);audioQueue.enqueue(prepared.file,prepared.manifest(),prepared.bodyHash,AudioSyncSession.origin(gatedArchive));q.enqueue(WireJson.bytes(fixture.get("material_event_2")));}
   AudioSyncSession gatedEngine=session(gated,text,audio,a->new AudioSyncSession.Catalog(text.account,gatedSessions,gatedArchives),()->{},http,now);requests=http.posts;AudioSyncSession.Status held=gatedEngine.run(false,2,8);yes(held.queued==1&&held.pumped==0&&held.prepared==0&&http.posts==requests);text(gated,material,fixture,now.get(),true);AudioSyncSession.Status resumed=gatedEngine.run(false,2,8,true);yes(resumed.retained==1&&resumed.prepared==0&&resumed.pumped>0);
   // Durable cursor rotates past an unsupported first source after restart.
   File fair=new File(files,"fair");yes(fair.mkdir());text(fair,material,fixture,now.get(),false);List<Object> fairSessions=LifelogAudioPayloadsTest.sessions(fair,now.get()),fairRows=new ArrayList<>();Map<String,Object> context=WireJson.object("account",text.account,"peer",LifelogAudioPayloadsTest.P,"generation",1L,"clock_epoch",LifelogAudioPayloadsTest.C);for(int i=0;i<2;i++)fairRows.add(WireJson.object("context",context,"stream",String.join("",Collections.nCopies(32,i==0?"d":"e")),"first_sequence",(long)i+1,"count",1L,"phase","sealed","error",""));fairRows.sort(Comparator.comparing(r->{try{return AudioSyncSession.origin(map(r));}catch(IOException e){throw new RuntimeException(e);}}));String message=new String(WireJson.bytes(WireJson.object("taskId",LifelogAudioPayloadsTest.TASK,"mode",1,"frameCount",2)),"UTF-8");for(int i=0;i<2;i++){Map<String,Object> a=map(fairRows.get(i));try(LifelogAudioArchive original=new LifelogAudioArchive(fair,text.account,LifelogAudioPayloadsTest.P,1,(String)a.get("stream"),()->{})){byte[] rawBatch=LifelogAudioPayloadsTest.wire(message,false);if(i==0)rawBatch[3]=(byte)0xa4;original.append(1,i==0?"A4":"A3",message,rawBatch,now.get(),10,LifelogAudioPayloadsTest.C,()->{});original.seal("capture_stopped",()->{});}}
   AudioSyncSession.Sources fairSource=a->new AudioSyncSession.Catalog(text.account,fairSessions,fairRows);AudioSyncSession.Status unsupported=session(fair,text,audio,fairSource,()->{},http,now).run(false,1,8);yes(unsupported.prepared==0&&unsupported.error.equals("AUDIO_PAYLOAD_BATCH_UNSUPPORTED"));now.addAndGet(30001);AudioSyncSession.Status progressed=session(fair,text,audio,fairSource,()->{},http,now).run(false,1,8);yes(progressed.prepared==1&&progressed.retained==1);
   // Interrupted scheduling hints are retained separately; queue receipts and
   // live permission checks remain authoritative for safe repeat discovery.
   Path schedule=new File(fair,"audio-auto-sync/"+audioConnection.binding()+"/"+text.account+"/state.json").toPath();Files.write(Paths.get(schedule+".partial"),new byte[]{'{'});now.addAndGet(1001);AudioSyncSession.Status recovered=session(fair,text,audio,fairSource,()->{},http,now).run(false,1,8);yes(recovered.attempted&&Files.exists(Paths.get(schedule+".interrupted"))&&!Files.exists(Paths.get(schedule+".partial")));
  }
  File original=LifelogAudioPayloadsTest.raw(files,map(archive.get(0)));Files.write(new File(files,"result.json").toPath(),WireJson.bytes(WireJson.object("rows",status.rows,"original_sha256",TaskWire.hash(bytes(original)),"checks",checks)));
  System.out.println("Audio automatic session "+mode+": "+checks+" assertions passed; synthetic HTTP/files, no phone");
 }
}
